// Source-only standalone A53 App. Profile generated by prepare_m3a_s1b.py.
#include "m3a_app.h"
#include "s1b_profile.h"
#include <cstdio>
alignas(64) static float cube[S1B_CUBE_BYTES/4], cls[2646], pos[15876];
alignas(64) static unsigned char weights[TT_ENGINE_WPKG16_BYTES];
alignas(64) static float patch[TT_ENGINE_PATCH_ELEMS];
alignas(64) static int16_t input[4*TT_ENGINE_IN_STRIDE/2];
alignas(64) static unsigned char output[64];
static TTM3aRoiResult results[15];
static TTM3aAppSession session{};
int main() {
    std::printf("S1B source=%s profile=longkou/v2; NOT a board acceptance test\n",S1B_SOURCE_REV);
    const TTM3aSdStorage storage={{{cube,sizeof(cube)},{cls,sizeof(cls)},
                                  {pos,sizeof(pos)},{weights,sizeof(weights)}}};
    const TTM3aRoiRequest roi={cube,sizeof(cube),400,550,406,0,0,5,3,cls,2646,pos,15876,4,100000000,
        patch,sizeof(patch),input,sizeof(input),output,sizeof(output),results,15};
    const int rc=tt_m3a_app_once(session,S1B_PROFILE,storage,roi);
    std::printf("S1B rc=%d sd_loaded=%u file=%d bytes=%lu fr=%d cleanup=%d driver=%d completed=%lu halted=%u\n",
        rc,unsigned(session.sd.loaded),session.sd.file_index,(unsigned long)session.sd.bytes_read,
        session.sd.fatfs_status,session.sd.cleanup_status,session.driver_status,
        (unsigned long)session.roi.completed,unsigned(session.roi.halted));
    // Only committed CPU results; never DMA output, guards, or failed suffix.
    for (size_t i=0; i<session.roi.completed; ++i)
        std::printf("ROI x=%lu y=%lu class_word=%08lX\n",(unsigned long)results[i].x,
                    (unsigned long)results[i].y,(unsigned long)results[i].packed_class);
    if (session.roi.halted) {
        std::puts("HALTED: external PL reset + App restart required; DMA buffers retained");
        for (;;) {} // no cleanup_platform(), cache disable, free, return or retry
    }
    return rc?1:0;
}
